// Nodes 210 and 211 must already exist in this model.
var start = new Node(210, 0, 0, 0);
var end = new Node(211, 4.5, 0, 0);
geometry.CreateMultipleBeamsExtended(geometry.Wrapper.Root,
    new[] { new Beam(310, start, end) });

// Use IDs that are unused in the target model; coordinates use its input units.
geometry.CreateMultipleNodesExtended(geometry.Wrapper.Root, new[]
{
    new Node(210, 0, 0, 0),
    new Node(211, 4.5, 0, 0)
});

// Both IDs must exist and be suitable for merging in the target model.
var retain = new Node(210, 0, 0, 0);
var redundant = new Node(212, 0, 0, 0);
geometry.MergeNodesExtended(geometry.Wrapper.Root, retain,
    new[] { retain, redundant });

// Primary case 17 and reference case 41 must already exist.
load.AddReferenceLoadsTo(17, new System.Collections.Generic.Dictionary<int, double>
{
    { 41, 1.25 }
});

// Primary target 17 and suitable source cases 41 and 42 must already exist.
load.AddRepeatLoadsTo(17, new System.Collections.Generic.Dictionary<int, double>
{
    { 41, 1.5 },
    { 42, -0.75 }
});

// Primary case 17 and temperature-load entities 101/102 must already exist.
// nThreads preserves the signature; this port keeps COM calls on this thread.
load.AddAxialThermalGradientTo(17, new[] { 101, 102 }, -15.5, nThreads: 2);

// Case 17 and member 101 must already exist; numeric fields use model input units.
var groups = new System.Collections.Generic.Dictionary<ILoadCase,
    System.Collections.Generic.List<(MemberLoad Load, System.Collections.Generic.List<Beam> Beams)>>
{
    { new LoadCase(17), new System.Collections.Generic.List<(MemberLoad Load,
        System.Collections.Generic.List<Beam> Beams)>
        {
            (new MemberConcentratedLoad(LoadDirection.GlobalY, -7.25, 2.5),
             new System.Collections.Generic.List<Beam>
             { new Beam(101, new Node(1, 0, 0, 0), new Node(2, 5, 0, 0)) })
        }
    }
};
load.AddMemberLoadsFromGroupsByLoadCase(groups);

// Case 17 and nodes 10/11 must already exist; fields use model input units.
var groups = new System.Collections.Generic.Dictionary<ILoadCase,
    System.Collections.Generic.List<(NodalLoad Load, System.Collections.Generic.List<Node> Nodes)>>
{
    { new LoadCase(17), new System.Collections.Generic.List<(NodalLoad Load,
        System.Collections.Generic.List<Node> Nodes)>
        {
            (new NodalLoad(1, -2, 3, -4, 5, -6),
             new System.Collections.Generic.List<Node>
             { new Node(10, 0, 0, 0), new Node(11, 1, 0, 0) })
        }
    }
};
load.AddNodalLoadsFromGroupsByLoadCase(groups);

var beam = new Beam(101, new Node(1, 0, 0, 0), new Node(2, 5, 0, 0));
var groups = load.GetMemberLoadsGroupedByLoadCase(new[] { beam }, new[] { new LoadCase(17) });
Console.WriteLine(groups.Count);

var node = new Node(10, 0, 0, 0);
var groups = load.GetNodalLoadsGroupedByLoadCase(new[] { node }, new[] { new LoadCase(17) });
Console.WriteLine(groups.Count);

var beam = new Beam(101, new Node(1, 0, 0, 0), new Node(2, 5, 0, 0));
load.PopulateMemberConcentratedLoads(new[] { beam }, new[] { new LoadCase(17) });
Console.WriteLine(beam.MemberLoadItems.Count);

var beam = new Beam(101, new Node(1, 0, 0, 0), new Node(2, 5, 0, 0));
load.PopulateMemberConcentratedMoments(new[] { beam }, new[] { new LoadCase(17) });
Console.WriteLine(beam.MemberLoadItems.Count);

var beam = new Beam(101, new Node(1, 0, 0, 0), new Node(2, 5, 0, 0));
load.PopulateMemberLinearVaryingLoads(new[] { beam }, new[] { new LoadCase(17) });
Console.WriteLine(beam.MemberLoadItems.Count);

var beam = new Beam(101, new Node(1, 0, 0, 0), new Node(2, 5, 0, 0));
load.PopulateMemberTrapezoidalLoads(new[] { beam }, new[] { new LoadCase(17) });
Console.WriteLine(beam.MemberLoadItems.Count);

var beam = new Beam(101, new Node(1, 0, 0, 0), new Node(2, 5, 0, 0));
var populated = load.PopulateMemberLoads(new[] { beam }, new[] { new LoadCase(17) });
foreach (var item in populated) Console.WriteLine(item.MemberLoadItems.Count);

var start = new StaadPro.Interop.Entities.Node(1, 0, 0, 0);
var middle = new StaadPro.Interop.Entities.Node(2, 2, 0, 0);
var end = new StaadPro.Interop.Entities.Node(3, 4, 0, 0);
var segments = new[] {
    new StaadPro.Interop.Entities.Beam(11, start, middle),
    new StaadPro.Interop.Entities.Beam(12, end, middle) };
var reconstructed = StaadPro.Interop.Services.ConnectivityService.IdentifyPhysicalMembers(segments);
Console.WriteLine(reconstructed.Members.Count); // 1; no STAAD changes

var first = new StaadPro.Interop.Entities.Node(1, 0, 0, 0);
var last = new StaadPro.Interop.Entities.Node(2, 3, 0, 0);
var membersToGroup = new[] {
    new StaadPro.Interop.Entities.Member(1, first, last),
    new StaadPro.Interop.Entities.Member(2, last, first) };
var angleGroups = StaadPro.Interop.Services.ConnectivityService.GroupPhysicalMembersByPlanAngle(membersToGroup);
Console.WriteLine(System.Linq.Enumerable.Count(angleGroups)); // 1

var outline = new[] {
    new StaadPro.Interop.Entities.Node(1, 0, 0, 0),
    new StaadPro.Interop.Entities.Node(2, 4, 0, 0),
    new StaadPro.Interop.Entities.Node(3, 4, 0, 4),
    new StaadPro.Interop.Entities.Node(4, 0, 0, 4) };
var meshResult = StaadPro.Interop.Services.PolygonMeshGenerationService.GenerateMesh(outline, 100, 200);
Console.WriteLine(meshResult.Plates.Count); // 2; nothing written to STAAD
Console.WriteLine(meshResult.ReachedTargetQuality);

var beamToPopulate = new StaadPro.Interop.Entities.Beam(101,
    new StaadPro.Interop.Entities.Node(1, 0, 0, 0),
    new StaadPro.Interop.Entities.Node(2, 5, 0, 0));
load.PopulateMemberUniformlyDistributedLoads(new[] { beamToPopulate },
    new StaadPro.Interop.Entities.ILoadCase[] { new StaadPro.Interop.Entities.LoadCase(17) });
Console.WriteLine(beamToPopulate.MemberLoadItems.Count);

var beamToPopulate = new StaadPro.Interop.Entities.Beam(101,
    new StaadPro.Interop.Entities.Node(1, 0, 0, 0),
    new StaadPro.Interop.Entities.Node(2, 5, 0, 0));
load.PopulateMemberUniformMoments(new[] { beamToPopulate },
    new StaadPro.Interop.Entities.ILoadCase[] { new StaadPro.Interop.Entities.LoadCase(17) });
Console.WriteLine(beamToPopulate.MemberLoadItems.Count);

var nodeToRefresh = new StaadPro.Interop.Entities.Node(101, 0, 0, 0);
var refreshedNodes = load.PopulateNodalLoads(new[] { nodeToRefresh },
    new StaadPro.Interop.Entities.ILoadCase[] { new StaadPro.Interop.Entities.LoadCase(17) });
foreach (var refreshedNode in refreshedNodes)
    Console.WriteLine(refreshedNode.NodalLoadItems.Count);

bool allowWindEdit = false; // Enable only for a controlled model with suitable definition/node IDs.
if (allowWindEdit)
{
    int windStatus = load.AddWindDefinition(1, "North wind");
    Console.WriteLine(windStatus);
}

